      ]
    };

    var layerIds = [
      ["nuclear", "coal", "oil", "natural_gas", "biomass", "hydro", "wind", "solar", "geothermal"],
      ["thermal_power", "refining", "direct_use"],
      ["electricity_grid"],
      ["waste_heat", "transport", "industry", "buildings", "agriculture", "other"]
    ];

    function buildSankey() {
      if (typeof d3 === 'undefined') {
        setTimeout(buildSankey, 100);
        return;
      }

      var wrapper = document.getElementById('sankey-wrapper');
      wrapper.innerHTML = '';

      var width = 1200;
      var height = 800;
      var nodeWidth = 32;
      var padding = 20;

      var svg = d3.select('#sankey-wrapper').append('svg')
        .attr('width', '100%')
        .attr('height', '100%')
        .attr('viewBox', '0 0 ' + width + ' ' + height)
        .attr('preserveAspectRatio', 'xMidYMid meet');

