        .target(function(d) { return [nodeMap[d.target].x, nodeMap[d.target].y + d.ty + (d.value * ky) / 2]; });

      // Calculate path with custom control points for wide jumps
      function customLinkPath(d) {
        var x0 = nodeMap[d.source].x + nodeWidth;
        var y0 = nodeMap[d.source].y + d.sy + (d.value * ky) / 2;
        var x1 = nodeMap[d.target].x;
        var y1 = nodeMap[d.target].y + d.ty + (d.value * ky) / 2;

        // If link skips a column (x jump > 400px), flatten the curve slightly in the middle
        var xJump = x1 - x0;
        var xi = d3.interpolateNumber(x0, x1);
        var x2 = xi(0.4);
        var x3 = xi(0.6);
        return "M" + x0 + "," + y0 + 
               "C" + x2 + "," + y0 + 
               " " + x3 + "," + y1 + 
               " " + x1 + "," + y1;
      }

      var linkG = svg.append('g').selectAll('.link')
        .data(energyData.flows)
        .enter().append('path')
        .attr('class', 'link')
        .attr('d', customLinkPath)
        .attr('stroke', function(f) { 
          return f.target === 'waste_heat' ? 'rgba(239, 68, 68, 0.7)' : nodeMap[f.source].color; 
        })
        .attr('stroke-width', function(f) { return Math.max(1, f.value * ky); })
        .attr('stroke-opacity', function(f) { return f.target === 'waste_heat' ? 0.8 : 0.45; })
        .attr('stroke-linecap', 'butt');

      linkG.append('title')
        .text(function(f) { return nodeMap[f.source].label + " → " + nodeMap[f.target].label + "\n" + f.value.toFixed(1) + " EJ"; });

      var nodeG = svg.append('g').selectAll('.node')
        .data(energyData.nodes)
        .enter().append('g')
        .attr('class', 'node')
        .attr('transform', function(d) { return 'translate(' + d.x + ',' + d.y + ')'; });

      nodeG.append('rect')
        .attr('width', nodeWidth)
        .attr('height', function(d) { return Math.max(2, d.h); })
        .attr('fill', function(d) { return d.color; })
        .attr('rx', 4);

      // Node Titles
      nodeG.append('text')
        .attr('x', function(d) { return d.x < width / 2 ? nodeWidth + 10 : -10; })
        .attr('y', function(d) { return d.h / 2 - 2; })
        .attr('text-anchor', function(d) { return d.x < width / 2 ? 'start' : 'end'; })
        .text(function(d) { return d.label; });

      // Node Values
      nodeG.append('text')
        .attr('class', 'value-label')
        .attr('x', function(d) { return d.x < width / 2 ? nodeWidth + 10 : -10; })
        .attr('y', function(d) { return d.h / 2 + 16; })
        .attr('text-anchor', function(d) { return d.x < width / 2 ? 'start' : 'end'; })
        .text(function(d) { return d.value.toFixed(1) + ' EJ'; });

      nodeG.append('title')
        .text(function(d) { return d.label + "\nTotal Flow: " + d.value.toFixed(1) + " EJ"; });
    }

    function onThemeChange() {
      // D3 redraws dynamically, theme colors use CSS vars so SVG text updates automatically
      // We don't necessarily need to redraw, but re-evaluating text styles is safe
      buildSankey();
    }

    document.addEventListener('DOMContentLoaded', buildSankey);
  </script>
