        {id: "industry", stage: "end_use", label: "Industry", color: "#4F46E5"},
        {id: "buildings", stage: "end_use", label: "Buildings", color: "#7C3AED"},
        {id: "agriculture", stage: "end_use", label: "Agriculture", color: "#9333EA"},
        {id: "other", stage: "end_use", label: "Other", color: "#A855F7"},
        {id: "waste_heat", stage: "end_use", label: "Waste / Rejected Heat", color: "#EF4444"}
      ],
      flows: [
        {source: "coal", target: "thermal_power", value: 96.5},
        {source: "natural_gas", target: "thermal_power", value: 42.8},
        {source: "oil", target: "thermal_power", value: 8.2},
        {source: "nuclear", target: "thermal_power", value: 29.4},
        {source: "oil", target: "refining", value: 162.3},
        {source: "natural_gas", target: "refining", value: 18.5},
        {source: "natural_gas", target: "direct_use", value: 80.2},
        {source: "coal", target: "direct_use", value: 60.8},
        {source: "biomass", target: "direct_use", value: 42.6},
        {source: "hydro", target: "electricity_grid", value: 15.8},
        {source: "wind", target: "electricity_grid", value: 8.4},
        {source: "solar", target: "electricity_grid", value: 5.9},
        {source: "geothermal", target: "electricity_grid", value: 1.0},
        {source: "thermal_power", target: "electricity_grid", value: 68.2},
        {source: "thermal_power", target: "waste_heat", value: 108.7},
        {source: "refining", target: "transport", value: 118.6},
        {source: "refining", target: "industry", value: 35.4},
        {source: "refining", target: "waste_heat", value: 26.8},
        {source: "electricity_grid", target: "buildings", value: 38.2},
        {source: "electricity_grid", target: "industry", value: 36.8},
        {source: "electricity_grid", target: "transport", value: 4.1},
        {source: "electricity_grid", target: "agriculture", value: 7.6},
        {source: "electricity_grid", target: "other", value: 12.6},
        {source: "direct_use", target: "industry", value: 82.4},
        {source: "direct_use", target: "buildings", value: 56.7},
        {source: "direct_use", target: "agriculture", value: 12.3},
        {source: "direct_use", target: "waste_heat", value: 32.2}
      ]
    };

    var layerIds = [
      ["nuclear", "coal", "oil", "natural_gas", "biomass", "hydro", "wind", "solar", "geothermal"],
      ["thermal_power", "refining", "direct_use"],
      ["electricity_grid"],
      ["waste_heat", "transport", "industry", "buildings", "agriculture", "other"]
    ];

    function buildSankey() {
      var width = 1200;
      var height = 800;
      var nodeWidth = 24;
      var padding = 22;

      var svg = d3.select('#sankey-wrapper').append('svg')
        .attr('width', '100%')
        .attr('height', '100%')
        .attr('viewBox', '0 0 ' + width + ' ' + height)
        .attr('preserveAspectRatio', 'xMidYMid meet');

      var nodeMap = {};
      energyData.nodes.forEach(function(n) {
        n.inflows = [];
        n.outflows = [];
        n.value = 0;
        nodeMap[n.id] = n;
      });

      energyData.flows.forEach(function(f) {
        var src = nodeMap[f.source];
        var tgt = nodeMap[f.target];
        src.outflows.push(f);
        tgt.inflows.push(f);
      });

      var maxLayerValue = 0;
      layerIds.forEach(function(ids) {
        var sum = 0;
        ids.forEach(function(id) {
          var n = nodeMap[id];
          var sumIn = d3.sum(n.inflows, function(f) { return f.value; });
          var sumOut = d3.sum(n.outflows, function(f) { return f.value; });
          n.value = Math.max(sumIn, sumOut) || sumIn || sumOut;
          sum += n.value;
        });
        if (sum > maxLayerValue) maxLayerValue = sum;
      });

      var ky = (height - padding * 8) / maxLayerValue;

      layerIds.forEach(function(ids, lx) {
        var x = lx * (width - nodeWidth) / (layerIds.length - 1);
        var layerH = d3.sum(ids, function(id) { return nodeMap[id].value * ky; }) + padding * (ids.length - 1);
        var y = (height - layerH) / 2;

        if (lx === 2) {
          y = 400; // Drop grid slightly
        }

        ids.forEach(function(id) {
          var n = nodeMap[id];
          n.x = x;
          n.y = y;
          n.h = Math.max(2, n.value * ky);
          y += n.h + padding;
        });
      });

      energyData.nodes.forEach(function(n) {
        n.outflows.sort(function(a, b) { return nodeMap[a.target].y - nodeMap[b.target].y; });
        n.inflows.sort(function(a, b) { return nodeMap[a.source].y - nodeMap[b.source].y; });

        var sy = 0;
        n.outflows.forEach(function(f) {
          f.sy = sy;
          sy += f.value * ky;
        });

        var ty = 0;
        n.inflows.forEach(function(f) {
          f.ty = ty;
          ty += f.value * ky;
        });
      });

      function customLinkPath(d) {
        var x0 = nodeMap[d.source].x + nodeWidth;
        var y0 = nodeMap[d.source].y + d.sy + (d.value * ky) / 2;
        var x1 = nodeMap[d.target].x;
        var y1 = nodeMap[d.target].y + d.ty + (d.value * ky) / 2;

        var xi = d3.interpolateNumber(x0, x1);
        var x2 = xi(0.45);
        var x3 = xi(0.55);
        return "M" + x0 + "," + y0 + "C" + x2 + "," + y0 + " " + x3 + "," + y1 + " " + x1 + "," + y1;
      }

      svg.append('g').selectAll('.link')
        .data(energyData.flows)
        .enter().append('path')
        .attr('class', 'link')
        .attr('d', customLinkPath)
        .attr('stroke', function(f) { 
          return f.target === 'waste_heat' ? '#EF4444' : nodeMap[f.source].color; 
        })
        .attr('stroke-width', function(f) { return Math.max(1, f.value * ky); })
        .attr('stroke-opacity', function(f) { 
          return f.target === 'waste_heat' ? 0.7 : 0.35; 
        });

      var nodeG = svg.append('g').selectAll('.node')
        .data(energyData.nodes)
        .enter().append('g')
        .attr('class', 'node')
        .attr('transform', function(d) { return 'translate(' + d.x + ',' + d.y + ')'; });

      nodeG.append('rect')
        .attr('width', nodeWidth)
        .attr('height', function(d) { return d.h; })
        .attr('fill', function(d) { return d.color; })
        .attr('rx', 3);

      // We draw text twice: once for background stroke, once for fill to ensure readability

      // Node Titles
      nodeG.append('text')
        .attr('class', 'bg-text')
        .attr('x', function(d) { return d.x < width / 2 ? nodeWidth + 10 : -10; })
        .attr('y', function(d) { return d.h / 2 - 4; })
        .attr('text-anchor', function(d) { return d.x < width / 2 ? 'start' : 'end'; })
        .text(function(d) { return d.label; });

      nodeG.append('text')
        .attr('x', function(d) { return d.x < width / 2 ? nodeWidth + 10 : -10; })
        .attr('y', function(d) { return d.h / 2 - 4; })
        .attr('text-anchor', function(d) { return d.x < width / 2 ? 'start' : 'end'; })
        .text(function(d) { return d.label; });

      // Node Values
      nodeG.append('text')
        .attr('class', 'value-label bg-text')
        .attr('x', function(d) { return d.x < width / 2 ? nodeWidth + 10 : -10; })
        .attr('y', function(d) { return d.h / 2 + 14; })
        .attr('text-anchor', function(d) { return d.x < width / 2 ? 'start' : 'end'; })
        .text(function(d) { return d.value.toFixed(1) + ' EJ'; });

      nodeG.append('text')
        .attr('class', 'value-label')
        .attr('x', function(d) { return d.x < width / 2 ? nodeWidth + 10 : -10; })
        .attr('y', function(d) { return d.h / 2 + 14; })
        .attr('text-anchor', function(d) { return d.x < width / 2 ? 'start' : 'end'; })
        .text(function(d) { return d.value.toFixed(1) + ' EJ'; });

      // Mark charts built
      window.chartsBuilt = true;
    }

    // Build chart after d3 loads. Using local file URI so it's instantaneous.
    buildSankey();
  </script>
</body>
</html>
